import java.io.*;
import java.util.*;

public class Main {
    static class Reader {
        BufferedReader br;
        StringTokenizer st;
        Reader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        Reader in = new Reader();
        int n = in.nextInt();
        int b = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        List<Integer> cuts = new ArrayList<>();
        int balance = 0;
        for (int i = 0; i < n - 1; i++) {
            if (a[i] % 2 == 0) {
                balance--;
            } else {
                balance++;
            }
            if (balance == 0) {
                cuts.add(Math.abs(a[i + 1] - a[i]));
            }
        }

        Collections.sort(cuts);
        int sum = 0;
        int taken = 0;
        int ans = 0;
        for (int cost : cuts) {
            sum += cost;
            taken++;
            if (sum <= b) {
                ans = taken;
            }
        }
        System.out.println(ans);
    }
}
